return $input.all().map((item, index) => {
  const source = item.json.body ?? item.json;

  const eventId =
    typeof source.event_id === 'string' ? source.event_id.trim() : '';
  const requester =
    typeof source.requester === 'string' ? source.requester.trim() : '';
  const title =
    typeof source.title === 'string' ? source.title.trim() : '';
  const description =
    typeof source.description === 'string' ? source.description.trim() : '';

  const missingFields = [];

  if (!eventId) missingFields.push('event_id');
  if (!requester) missingFields.push('requester');
  if (!title) missingFields.push('title');
  if (!description) missingFields.push('description');

  if (missingFields.length > 0) {
    throw new Error(
      `Item ${index + 1}: missing or empty required fields: ${missingFields.join(', ')}`
    );
  }

  if (eventId.length > 100) {
    throw new Error(`Item ${index + 1}: event_id exceeds 100 characters`);
  }

  if (!/^[A-Za-z0-9._:-]+$/.test(eventId)) {
    throw new Error(
      `Item ${index + 1}: event_id contains unsupported characters`
    );
  }

  if (requester.length > 100) {
    throw new Error(`Item ${index + 1}: requester exceeds 100 characters`);
  }

  if (title.length > 200) {
    throw new Error(`Item ${index + 1}: title exceeds 200 characters`);
  }

  if (description.length > 5000) {
    throw new Error(`Item ${index + 1}: description exceeds 5000 characters`);
  }

  return {
    json: {
      event_id: eventId,
      requester,
      title,
      description,
    },
  };
});
